import {registerComments} from './comments.js';
import {registerRelations} from './relations.js';
import {AppError} from '@crew/shared';
import {labelInput} from '../../../../shared/src/schemas/issue.js';
import {getIssue,listIssues,createIssue,updateIssue,deleteIssue,publicLabel,validateIssueReferences,emitIssue} from './issues.js';
export function registerIssueRoutes(ctx) {
  registerComments(ctx);
  registerRelations(ctx);
  const {app,db,requireAuth,permissions:p}=ctx;
  const prefix='/api/v1';
  app.get(prefix+'/projects/:projectId/assignees',requireAuth,(req,res)=>{
    const project=p.assertProject(req,req.params.projectId,'project:read');
    const members=db.prepare('SELECT m.user_id AS userId,u.name,u.email,m.role,m.created_at AS createdAt FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.org_id=? ORDER BY u.name,u.id').all(project.org_id);
    const visible=members.filter(member=>p.canProject(member.userId,project.id,'project:read'));
    res.json(ctx.paginate(visible,req.query,'userId'));
  });
  function permitted(req,permission='project:read') {
    const issue=getIssue(ctx,req.params.issueId);
    p.assertProject(req,issue.projectId,permission);
    return issue;
  }
  app.get(prefix+'/projects/:projectId/issues',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'project:read');
    res.json(ctx.paginate(listIssues(ctx,req.params.projectId,req.query),req.query));
  });
  app.get(prefix+'/orgs/:orgId/issues',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'org:read');p.scope(req,'project:read');
    const projects=p.projectIds(req.user.id,req.params.orgId);
    const issues=projects.flatMap(projectId=>listIssues(ctx,projectId,req.query)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)||a.id.localeCompare(b.id));
    res.json(ctx.paginate(issues,req.query));
  });
  app.post(prefix+'/projects/:projectId/issues',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'issue:write');
    res.status(201).json({issue:createIssue(ctx,req,req.params.projectId,req.body)});
  });
  app.get(prefix+'/issues/:issueId',requireAuth,(req,res)=>res.json({issue:permitted(req)}));
  app.patch(prefix+'/issues/:issueId',requireAuth,(req,res)=>{
    permitted(req,'issue:write');res.json({issue:updateIssue(ctx,req,req.params.issueId,req.body)});
  });
  app.delete(prefix+'/issues/:issueId',requireAuth,(req,res)=>{
    permitted(req,'issue:write');deleteIssue(ctx,req,req.params.issueId);res.json({ok:true});
  });
  app.get(prefix+'/projects/:projectId/labels',requireAuth,(req,res)=>{
    p.assertProject(req,req.params.projectId,'project:read');
    res.json(ctx.paginate(db.prepare('SELECT * FROM labels WHERE project_id=? ORDER BY name,id').all(req.params.projectId).map(publicLabel),req.query));
  });
  app.post(prefix+'/projects/:projectId/labels',requireAuth,(req,res)=>{
    const project=p.assertProject(req,req.params.projectId,'issue:write');
    validateIssueReferences(ctx,project.id,{});
    const input=labelInput(req.body),id=ctx.id(),time=ctx.now();
    if(db.prepare('SELECT 1 FROM labels WHERE project_id=? AND name=?').get(project.id,input.name))throw new AppError('CONFLICT','Label name already exists',409);
    db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run(id,project.id,input.name,input.color,time,time);
    const label=publicLabel(db.prepare('SELECT * FROM labels WHERE id=?').get(id));
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:id,action:'created',before:null,after:label,time});
    res.status(201).json({label});
  });
  function editableLabel(req) {
    const row=db.prepare('SELECT * FROM labels WHERE id=?').get(req.params.labelId);
    if(!row)throw new AppError('NOT_FOUND','Label not found',404);
    const project=p.assertProject(req,row.project_id,'issue:write');
    validateIssueReferences(ctx,project.id,{});
    return {row,project};
  }
  app.patch(prefix+'/labels/:labelId',requireAuth,(req,res)=>{
    const {row,project}=editableLabel(req),input=labelInput(req.body,{partial:true});
    if(input.name&&db.prepare('SELECT 1 FROM labels WHERE project_id=? AND name=? AND id<>?').get(project.id,input.name,row.id))throw new AppError('CONFLICT','Label name already exists',409);
    const affected=db.prepare('SELECT issue_id FROM issue_labels WHERE label_id=?').all(row.id).map(item=>getIssue(ctx,item.issue_id));
    db.prepare('UPDATE labels SET name=?,color=?,updated_at=? WHERE id=?').run(input.name??row.name,input.color??row.color,ctx.now(),row.id);
    const label=publicLabel(db.prepare('SELECT * FROM labels WHERE id=?').get(row.id));
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:row.id,action:'updated',before:publicLabel(row),after:label,time:ctx.now()});
    for(const before of affected)emitIssue(ctx,req,'updated',before,getIssue(ctx,before.id));
    res.json({label});
  });
  app.delete(prefix+'/labels/:labelId',requireAuth,(req,res)=>{
    const {row,project}=editableLabel(req);
    const affected=db.prepare('SELECT issue_id FROM issue_labels WHERE label_id=?').all(row.id).map(item=>getIssue(ctx,item.issue_id));
    db.prepare('DELETE FROM labels WHERE id=?').run(row.id);
    ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'label',entityId:row.id,action:'deleted',before:publicLabel(row),after:null,time:ctx.now()});
    for(const before of affected)emitIssue(ctx,req,'updated',before,getIssue(ctx,before.id));
    res.json({ok:true});
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function scenario(fn) {
  const server=await testServer();
  try{
    const request=server.agent();
    const signup=await request('POST','/auth/signup',{name:'Owner',email:'owner@example.test',password:'correct-horse-battery'});
    assert.equal(signup.status,201);
    const user=signup.data.user;
    const {data:{organization}}=await request('POST','/orgs',{name:'Issue team'});
    const created=await request('POST','/orgs/'+organization.id+'/projects',{key:'ISS',name:'Issue project'});
    assert.equal(created.status,201);
    const project=created.data.project;
    const create=async body=>request('POST','/projects/'+project.id+'/issues',body);
    await fn({server,request,user,organization,project,create});
  }finally{await server.close();}
}
test('issues persist every field and hydrate labels status and identities',()=>scenario(async({request,project,user,create})=>{
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Backend',color:'#ABCDEF'})).data.label;
  const parent=(await create({title:'Parent'})).data.issue;
  const result=await create({title:'Ship',description:'# Plan\nDetails',statusId:project.statuses[1].id,priority:2,assigneeId:user.id,estimate:2.5,dueDate:'2028-02-29',parentId:parent.id,labelIds:[label.id]});
  assert.equal(result.status,201);const issue=result.data.issue;
  assert.equal(issue.key,'ISS-2');assert.equal(issue.statusCategory,'active');assert.equal(issue.assignee.id,user.id);assert.equal(issue.creator.name,'Owner');
  for(const [key,value] of Object.entries({title:'Ship',description:'# Plan\nDetails',priority:2,estimate:2.5,dueDate:'2028-02-29',parentId:parent.id}))assert.equal(issue[key],value);
  assert.equal(issue.labels[0].name,'Backend');assert.equal(issue.labels[0].color,'#abcdef');
  assert.deepEqual((await request('GET','/issues/'+issue.id)).data.issue,issue);
}));
test('issue numbering is independent per project and never reuses deletion gaps',()=>scenario(async({request,organization,project,create})=>{
  const first=(await create({title:'One'})).data.issue;await request('DELETE','/issues/'+first.id);
  assert.equal((await create({title:'Two'})).data.issue.number,2);
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'NEW',name:'Other'})).data.project;
  assert.equal((await request('POST','/projects/'+other.id+'/issues',{title:'Other one'})).data.issue.key,'NEW-1');
  assert.equal((await request('GET','/projects/'+project.id)).data.project.nextIssueNumber,3);
}));
test('invalid issue creation rolls back numbering and all fields',()=>scenario(async({request,project,create})=>{
  const result=await create({title:'Invalid',statusId:'missing'});assert.equal(result.status,422);assert.ok(result.data.error.details.statusId);
  assert.equal((await create({title:'Valid'})).data.issue.number,1);assert.equal((await request('GET','/projects/'+project.id+'/issues')).data.items.length,1);
}));
test('issue parents cannot cross projects or form ancestry cycles',()=>scenario(async({request,create,organization})=>{
  const parent=(await create({title:'Parent'})).data.issue;
  const child=(await create({title:'Child',parentId:parent.id})).data.issue;
  assert.equal((await request('PATCH','/issues/'+parent.id,{parentId:child.id})).status,422);
  assert.equal((await request('PATCH','/issues/'+parent.id,{parentId:parent.id})).status,422);
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'OTH',name:'Other'})).data.project;
  assert.equal((await request('POST','/projects/'+other.id+'/issues',{title:'Wrong parent',parentId:parent.id})).status,422);
}));
test('status labels and assignee must belong to the accessible project',()=>scenario(async({request,create,organization})=>{
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'OTH',name:'Other'})).data.project;
  const label=(await request('POST','/projects/'+other.id+'/labels',{name:'Other label'})).data.label;
  assert.equal((await create({title:'Wrong status',statusId:other.statuses[0].id})).status,422);
  assert.equal((await create({title:'Wrong label',labelIds:[label.id]})).status,422);
  assert.equal((await create({title:'Wrong assignee',assigneeId:'unknown'})).status,422);
}));
test('editing issue fields preserves omitted fields and clears nullable values',()=>scenario(async({request,create,user})=>{
  const issue=(await create({title:'Original',description:'Keep',estimate:5,dueDate:'2026-12-01',assigneeId:user.id})).data.issue;
  const result=await request('PATCH','/issues/'+issue.id,{title:'Changed',estimate:null,dueDate:null,assigneeId:null});
  assert.equal(result.status,200);assert.equal(result.data.issue.description,'Keep');assert.equal(result.data.issue.estimate,null);assert.equal(result.data.issue.dueDate,null);assert.equal(result.data.issue.assignee,null);
}));
test('issue list combines filters and uses opaque cursor pages',()=>scenario(async({request,project,create})=>{
  await create({title:'First',priority:1});await create({title:'Second',priority:2});await create({title:'Third',priority:2});
  const first=(await request('GET','/projects/'+project.id+'/issues?priority=2&limit=1')).data;
  assert.equal(first.items[0].title,'Third');assert.ok(first.nextCursor);
  const second=(await request('GET','/projects/'+project.id+'/issues?priority=2&limit=1&cursor='+first.nextCursor)).data;
  assert.equal(second.items[0].title,'Second');assert.equal(second.nextCursor,null);
  assert.equal((await request('GET','/projects/'+project.id+'/issues?q=FIRST')).data.items[0].title,'First');
}));
test('labels are project unique and propagate updates to issue snapshots',()=>scenario(async({server,request,project,create})=>{
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Bug'})).data.label;
  assert.equal((await request('POST','/projects/'+project.id+'/labels',{name:'bug'})).status,409);
  const issue=(await create({title:'Fix',labelIds:[label.id]})).data.issue;
  const events=[];server.ctx.bus.subscribe(event=>events.push(event));
  assert.equal((await request('PATCH','/labels/'+label.id,{name:'Defect',color:'#ff0000'})).status,200);
  assert.equal((await request('GET','/issues/'+issue.id)).data.issue.labels[0].name,'Defect');
  assert.ok(events.some(event=>event.entityType==='issue'&&event.after.labels[0].name==='Defect'));
  await request('DELETE','/labels/'+label.id);assert.deepEqual((await request('GET','/issues/'+issue.id)).data.issue.labels,[]);
}));
test('every issue mutation emits full actor org project and before-after records',()=>scenario(async({server,request,project,user,organization,create})=>{
  const events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const issue=(await create({title:'Event',description:'Searchable'})).data.issue;
  await request('PATCH','/issues/'+issue.id,{priority:1});await request('DELETE','/issues/'+issue.id);
  const changes=events.filter(event=>event.entityType==='issue');assert.deepEqual(changes.map(event=>event.action),['created','updated','deleted']);
  assert.equal(changes[0].actorId,user.id);assert.equal(changes[0].orgId,organization.id);assert.equal(changes[0].projectId,project.id);assert.equal(changes[0].after.description,'Searchable');assert.deepEqual(changes[0].after.labels,[]);
  assert.equal(changes[1].before.priority,0);assert.equal(changes[1].after.priority,1);assert.equal(changes[2].after,null);
}));
test('guest issue access is filtered before organization cursor pagination',()=>scenario(async({server,request,project,organization,create})=>{
  const issue=(await create({title:'Visible'})).data.issue;
  const other=(await request('POST','/orgs/'+organization.id+'/projects',{key:'OTH',name:'Private'})).data.project;
  const hidden=(await request('POST','/projects/'+other.id+'/issues',{title:'Hidden'})).data.issue;
  const guest=server.agent();const signup=await guest('POST','/auth/signup',{name:'Guest',email:'guest@example.test',password:'correct-horse-battery'});
  await request('POST','/orgs/'+organization.id+'/members',{userId:signup.data.user.id,role:'guest'});
  await request('POST','/projects/'+project.id+'/guests',{userId:signup.data.user.id});
  assert.equal((await guest('GET','/issues/'+issue.id)).status,200);assert.equal((await guest('GET','/issues/'+hidden.id)).status,403);
  assert.equal((await guest('POST','/projects/'+project.id+'/issues',{title:'Forbidden'})).status,403);
  const page=(await guest('GET','/orgs/'+organization.id+'/issues?limit=1')).data;assert.deepEqual(page.items.map(item=>item.id),[issue.id]);assert.equal(page.nextCursor,null);
}));
test('archived projects retain reads while rejecting issue mutations',()=>scenario(async({request,project,create})=>{
  const issue=(await create({title:'Retained'})).data.issue;await request('PATCH','/projects/'+project.id,{archived:true});
  assert.equal((await request('GET','/issues/'+issue.id)).status,200);assert.equal((await create({title:'Blocked'})).status,409);assert.equal((await request('PATCH','/issues/'+issue.id,{title:'Blocked'})).status,409);assert.equal((await request('DELETE','/issues/'+issue.id)).status,409);
}));
test('deleting parent preserves children and deleting issue clears label joins',()=>scenario(async({server,request,project,create})=>{
  const parent=(await create({title:'Parent'})).data.issue;
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Keep'})).data.label;
  const child=(await create({title:'Child',parentId:parent.id,labelIds:[label.id]})).data.issue;
  await request('DELETE','/issues/'+parent.id);assert.equal((await request('GET','/issues/'+child.id)).data.issue.parentId,null);
  await request('DELETE','/issues/'+child.id);assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM issue_labels').get().n,0);
}));

test('issue descriptions resolve visible mentions in full event snapshots',()=>scenario(async({server,create,user})=>{
  const events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const issue=(await create({title:'Mention',description:'@[Owner](user:'+user.id+')'})).data.issue;
  assert.deepEqual(issue.mentionedUserIds,[user.id]);assert.deepEqual(events.find(event=>event.entityType==='issue').after.mentionedUserIds,[user.id]);
}));
test('issue status edits append consistently to the destination board column',()=>scenario(async({request,project,create})=>{
  const a=(await create({title:'A'})).data.issue,b=(await create({title:'B',statusId:project.statuses[1].id})).data.issue;
  const moved=(await request('PATCH','/issues/'+a.id,{statusId:project.statuses[1].id})).data.issue;assert.ok(moved.rank>b.rank);
}));
test('invalid issue list priority returns a stable field validation error',()=>scenario(async({request,project})=>{
  const result=await request('GET','/projects/'+project.id+'/issues?priority=bad');assert.equal(result.status,422);assert.ok(result.data.error.details.priority);
}));

test('assignee and mention candidates include only project-visible people before pagination',()=>scenario(async({server,request,organization,project,user})=>{
  const guest=server.agent();const signup=await guest('POST','/auth/signup',{name:'A Hidden Guest',email:'hidden@example.test',password:'correct-horse-battery'});
  await request('POST','/orgs/'+organization.id+'/members',{userId:signup.data.user.id,role:'guest'});
  const page=(await request('GET','/projects/'+project.id+'/assignees?limit=1')).data;assert.equal(page.items[0].userId,user.id);assert.equal(page.nextCursor,null);
  assert.equal((await guest('GET','/projects/'+project.id+'/assignees')).status,403);
  await request('POST','/projects/'+project.id+'/guests',{userId:signup.data.user.id});
  const visible=(await guest('GET','/projects/'+project.id+'/assignees')).data.items;assert.equal(visible.length,2);assert.ok(visible.some(item=>item.userId===signup.data.user.id));
}));

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Field,Button,Notice} from '../../components/ui.jsx';
import {PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {issueForm,issuePayload,toggleLabel,issueErrors,eligibleParents} from './issue-state.js';
export function IssueEditor({issue,project,members=[],labels=[],issues=[],onSave,onCancel}) {
  const [form,setForm]=useState(()=>issueForm(issue));
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  const errors=issueErrors(error);
  function change(field,value){setForm(previous=>({...previous,[field]:value}));}
  function input(field){return event=>change(field,event.currentTarget.value);}
  async function submit(event) {
    event.preventDefault();setError(null);setBusy(true);
    try {await onSave(issuePayload(form));}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  return <form className="issue-editor" onSubmit={submit}>
    <Notice error={error}/>
    <fieldset disabled={busy}>
      <legend>{issue?'Edit issue':'New issue'}</legend>
      <Field label="Title" name="title" required maxLength={300} value={form.title} onInput={input('title')} error={errors.title}/>
      <Field label="Description (Markdown)" error={errors.description}><textarea name="description" rows="8" maxLength={100000} value={form.description} onInput={input('description')}/></Field>
      <p className="field-help">Use headings, lists, links, code, and @mentions. Raw HTML is displayed as text.</p>
      <div className="form-grid">
        <Field label="Status" error={errors.statusId}><select name="statusId" value={form.statusId} onChange={input('statusId')}><option value="">First workflow status</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
        <Field label="Priority" error={errors.priority}><select name="priority" value={form.priority} onChange={input('priority')}>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
        <Field label="Assignee" error={errors.assigneeId}>
          <input name="assigneeId" list="issue-assignee-choices" value={form.assigneeId} onInput={input('assigneeId')} placeholder="Unassigned; select or paste a user ID"/>
          <datalist id="issue-assignee-choices">{members.map(member=><option key={member.userId} value={member.userId}>{member.name} · {member.email}</option>)}</datalist>
        </Field>
        <Field label="Estimate" name="estimate" type="number" min="0" max="1000000" step="any" value={form.estimate} onInput={input('estimate')} error={errors.estimate}/>
        <Field label="Due date" name="dueDate" type="date" value={form.dueDate} onInput={input('dueDate')} error={errors.dueDate}/>
        <Field label="Parent issue" error={errors.parentId}>
          <input name="parentId" list="parent-issue-choices" value={form.parentId} onInput={input('parentId')} placeholder="No parent; select or paste an issue ID"/>
          <datalist id="parent-issue-choices">{eligibleParents(issues,issue?.id).map(parent=><option key={parent.id} value={parent.id}>{parent.key} · {parent.title}</option>)}</datalist>
        </Field>
      </div>
      <fieldset className="label-picker"><legend>Labels</legend>{labels.length?labels.map(label=><label key={label.id}><input type="checkbox" checked={form.labelIds.includes(label.id)} onChange={()=>change('labelIds',toggleLabel(form.labelIds,label.id))}/><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span></label>):<p>Create project labels to categorize this issue.</p>}{errors.labelIds&&<small role="alert">{errors.labelIds}</small>}</fieldset>
    </fieldset>
    <div className="actions"><Button busy={busy} type="submit">{issue?'Save issue':'Create issue'}</Button><Button type="button" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </form>;
}

import {Markdown,IssueComments,IssueRelations} from './issue-discussion.jsx';
import '../../styles/issues.css';
import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Notice,Loading,Empty,Button,Field,useLoad,ConfirmButton} from '../../components/ui.jsx';
import {priorityLabel,PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {IssueEditor} from './issue-editor.jsx';
import {issueListFilters,mergeIssuePages,relativeDue} from './issue-state.js';
export async function loadIssueContext(api,projectId) {
  const {project,permissions}=await api.get('/projects/'+projectId);
  const [members,labels,issues]=await Promise.all([
    api.get('/projects/'+projectId+'/assignees?limit=200'),
    api.get('/projects/'+projectId+'/labels?limit=200'),
    api.get('/projects/'+projectId+'/issues?limit=200')
  ]);
  return {project,permissions,members:members.items,labels:labels.items,issues:issues.items};
}
function canEdit(context,user) {
  return !context.project.archived&&context.permissions.write;
}
export function IssueSummary({issue}) {
  const due=relativeDue(issue.dueDate);
  return <article className="issue-summary">
    <div><a href={'#/issues/'+issue.id}><strong>{issue.key}</strong> {issue.title}</a><p>{issue.statusName} · {priorityLabel(issue.priority)} · {issue.assignee?.name??'Unassigned'}</p></div>
    <div className="issue-tags">{issue.labels.map(label=><span key={label.id} className="label-chip" style={{borderColor:label.color}}>{label.name}</span>)}{issue.estimate!==null&&<span>{issue.estimate} points</span>}{issue.dueDate&&<span className={due.overdue?'overdue':''}>{due.label}</span>}</div>
  </article>;
}
export function Issues({params,api,navigate,user}) {
  const context=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [filters,setFilters]=useState({});
  const [creating,setCreating]=useState(false);
  const [items,setItems]=useState([]);
  const [cursor,setCursor]=useState(null);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  const serialized=JSON.stringify(issueListFilters(filters));
  const results=useLoad(()=>api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams(JSON.parse(serialized))),[params.projectId,serialized]);
  useEffect(()=>{if(results.data){setItems(results.data.items);setCursor(results.data.nextCursor);}},[results.data]);
  function filter(field,value){setFilters(previous=>({...previous,[field]:value}));}
  async function more(){
    setBusy(true);setError(null);
    try{const page=await api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams({...issueListFilters(filters),cursor}));setItems(previous=>mergeIssuePages(previous,page.items));setCursor(page.nextCursor);}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  if(context.loading)return <Loading/>;
  if(context.error)return <Notice error={context.error}/>;
  const {project,members,labels}=context.data;
  const editable=canEdit(context.data,user);
  return <Page title={project.key+' issues'} actions={<><a href={'#/projects/'+project.id}>Project</a><a href={'#/projects/'+project.id+'/board'}>Board</a><a href={'#/projects/'+project.id+'/labels'}>Labels</a>{editable&&<Button onClick={()=>setCreating(true)}>New issue</Button>}</>}>
    <Notice error={error??results.error}/>
    {project.archived&&<Notice>This project is archived and read-only.</Notice>}
    {creating&&<IssueEditor {...context.data} onCancel={()=>setCreating(false)} onSave={async body=>{const {issue}=await api.post('/projects/'+project.id+'/issues',body);navigate('/issues/'+issue.id);}}/>}
    <div className="issue-filters" role="search" aria-label="Filter issues">
      <Field label="Search issues" name="q" type="search" value={filters.q??''} onInput={event=>filter('q',event.currentTarget.value)}/>
      <Field label="Status"><select value={filters.statusId??''} onChange={event=>filter('statusId',event.currentTarget.value)}><option value="">All statuses</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
      <Field label="Assignee"><select value={filters.assigneeId??''} onChange={event=>filter('assigneeId',event.currentTarget.value)}><option value="">Anyone</option>{members.map(member=><option key={member.userId} value={member.userId}>{member.name}</option>)}</select></Field>
      <Field label="Label"><select value={filters.labelId??''} onChange={event=>filter('labelId',event.currentTarget.value)}><option value="">All labels</option>{labels.map(label=><option key={label.id} value={label.id}>{label.name}</option>)}</select></Field>
      <Field label="Priority"><select value={filters.priority??''} onChange={event=>filter('priority',event.currentTarget.value)}><option value="">All priorities</option>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
      <Button type="button" onClick={()=>setFilters({})}>Clear filters</Button>
    </div>
    {results.loading?<Loading/>:items.length?<div className="issue-list">{items.map(issue=><IssueSummary key={issue.id} issue={issue}/>)}</div>:<Empty>No issues match these filters.</Empty>}
    {cursor&&<Button busy={busy} onClick={more}>Load more issues</Button>}
  </Page>;
}
export function IssueDetail({params,api,navigate,user}) {
  const [editing,setEditing]=useState(false);
  const [error,setError]=useState(null);
  const result=useLoad(async()=>{
    const {issue}=await api.get('/issues/'+params.issueId);
    const [context,parent]=await Promise.all([
      loadIssueContext(api,issue.projectId),
      issue.parentId?api.get('/issues/'+issue.parentId).then(result=>result.issue):null
    ]);
    return {issue,parent,...context};
  },[params.issueId]);
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const {issue,issues,parent}=result.data;
  const editable=canEdit(result.data,user);
  const children=issues.filter(item=>item.parentId===issue.id);
  const due=relativeDue(issue.dueDate);
  async function remove(){
    try{await api.delete('/issues/'+issue.id);navigate('/projects/'+issue.projectId+'/issues');}catch(error){setError(error);}
  }
  return <Page title={issue.key+' · '+issue.title} actions={<><a href={'#/projects/'+issue.projectId+'/issues'}>All issues</a>{editable&&<Button onClick={()=>setEditing(value=>!value)}>{editing?'Close editor':'Edit issue'}</Button>}</>}>
    <Notice error={error}/>
    {editing?<IssueEditor key={issue.updatedAt} {...result.data} onCancel={()=>setEditing(false)} onSave={async body=>{await api.patch('/issues/'+issue.id,body);setEditing(false);result.reload();}}/>:<>
      <section aria-label="Description"><h2>Description</h2><Markdown source={issue.description||'No description yet.'}/></section>
      <dl className="issue-properties"><dt>Status</dt><dd>{issue.statusName}</dd><dt>Priority</dt><dd>{priorityLabel(issue.priority)}</dd><dt>Assignee</dt><dd>{issue.assignee?.name??'Unassigned'}</dd><dt>Estimate</dt><dd>{issue.estimate??'Not estimated'}</dd><dt>Due</dt><dd className={due.overdue?'overdue':''}>{due.label}</dd><dt>Created by</dt><dd>{issue.creator.name}</dd><dt>Created</dt><dd><time dateTime={issue.createdAt}>{new Date(issue.createdAt).toLocaleString()}</time></dd><dt>Updated</dt><dd><time dateTime={issue.updatedAt}>{new Date(issue.updatedAt).toLocaleString()}</time></dd><dt>Parent</dt><dd>{parent?<a href={'#/issues/'+parent.id}>{parent.key} · {parent.title}</a>:'No parent issue'}</dd></dl>
      <section><h2>Labels</h2>{issue.labels.length?issue.labels.map(label=><span className="label-chip" key={label.id} style={{borderColor:label.color}}>{label.name}</span>):<Empty>No labels assigned.</Empty>}</section>
      {children.length>0&&<section><h2>Child issues</h2>{children.map(child=><IssueSummary key={child.id} issue={child}/>)}</section>}
      <IssueRelations issue={issue} issues={issues} api={api} editable={editable}/><IssueComments issue={{...issue,archived:result.data.project.archived}} api={api} user={user} members={result.data.members} canAdmin={result.data.permissions.manage}/>{editable&&<div className="danger-zone"><ConfirmButton message={'Delete '+issue.key+' permanently?'} onConfirm={remove}>Delete issue</ConfirmButton></div>}
    </>}
  </Page>;
}
export function ProjectLabels({params,api,user}) {
  const result=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [name,setName]=useState('');const [color,setColor]=useState('#5965d8');
  const [editing,setEditing]=useState(null);const [error,setError]=useState(null);const [busy,setBusy]=useState(false);
  async function save(event){
    event.preventDefault();setBusy(true);setError(null);
    try{if(editing)await api.patch('/labels/'+editing,{name,color});else await api.post('/projects/'+params.projectId+'/labels',{name,color});setEditing(null);setName('');result.reload();}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  async function remove(label){try{await api.delete('/labels/'+label.id);result.reload();}catch(error){setError(error);}}
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const editable=canEdit(result.data,user);
  return <Page title={result.data.project.key+' labels'} actions={<a href={'#/projects/'+params.projectId+'/issues'}>Issues</a>}>
    <Notice error={error}/>
    {editable&&<form onSubmit={save}><Field label="Label name" name="name" value={name} required maxLength={60} onInput={event=>setName(event.currentTarget.value)}/><Field label="Color" name="color" type="color" value={color} onInput={event=>setColor(event.currentTarget.value)}/><Button busy={busy}>{editing?'Save label':'Create label'}</Button>{editing&&<Button type="button" onClick={()=>{setEditing(null);setName('');}}>Cancel editing</Button>}</form>}
    {result.data.labels.length?<ul>{result.data.labels.map(label=><li key={label.id}><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span>{editable&&<><Button onClick={()=>{setEditing(label.id);setName(label.name);setColor(label.color);}}>Edit {label.name}</Button><ConfirmButton message={'Remove '+label.name+' from this project and its issues?'} onConfirm={()=>remove(label)}>Delete {label.name}</ConfirmButton></>}</li>)}</ul>:<Empty>No labels yet.</Empty>}
  </Page>;
}
